def minimumCardPickup(cards):
    min_len = float('inf')
    n = len(cards)
    for i in range(n):
        for j in range(i + 1, n):
            if cards[i] == cards[j]:
                min_len = min(min_len, j - i + 1)
                break
    return min_len if min_len != float('inf') else -1

