def minimumCardPickup(cards):
    last_seen = {}
    min_dist = float('inf')
    for i, card in enumerate(cards):
        if card in last_seen:
            min_dist = min(min_dist, i - last_seen[card] + 1)
        last_seen[card] = i
    return min_dist if min_dist != float('inf') else -1

