#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;
class Solution {
public:
    int minimumCardPickup(vector<int>& cards) {
        unordered_map<int, int> lastSeen;
        int minDist = 1e9;
        for (int i = 0; i < (int)cards.size(); i++) {
            if (lastSeen.count(cards[i])) {
                minDist = min(minDist, i - lastSeen[cards[i]] + 1);
            }
            lastSeen[cards[i]] = i;
        }
        return minDist == 1e9 ? -1 : minDist;
    }
};
